// Same fractal-noise grain used by the Voxide marketing site's own texture
// overlay — offered as a widget "skin" so a developer's grainy/matte page can
// keep its identity instead of Voxide always looking glossy-flat.
const NOISE_SVG_URL =
  "url(\"data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E\")";

function hexToRgba(hex: string, alpha: number): string {
  let h = (hex || "").replace("#", "");
  if (h.length === 3) h = h.split("").map((c) => c + c).join(""); // #fff -> #ffffff
  if (h.length !== 6) return hex;
  const r = parseInt(h.slice(0, 2), 16), g = parseInt(h.slice(2, 4), 16), b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

// ---------------------------------------------------------------------------
// Hotkey — `ui.hotkeyActivate` / `ui.hotkeyDeactivate` (see types.ts). Parsing
// and matching are kept as plain functions (no dependency on component state)
// so they're trivial to reason about and cheap to re-derive with useMemo.
// ---------------------------------------------------------------------------

const HOTKEY_MODIFIER_ALIASES: Record<string, "ctrl" | "alt" | "shift" | "meta"> = {
  control: "ctrl", ctrl: "ctrl",
  alt: "alt", option: "alt",
  shift: "shift",
  meta: "meta", cmd: "meta", command: "meta", win: "meta", windows: "meta",
};

interface ParsedHotkey {
  ctrl: boolean;
  alt: boolean;
  shift: boolean;
  meta: boolean;
  /** Lowercased, space-normalised trigger key (e.g. "k", "escape", "space"). */
  key: string;
  /** No modifier at all — a single bare key. Gated separately in the keydown
   *  handler so it doesn't fire while a visitor is typing in a text field. */
  bare: boolean;
}

/** `"alt+k"` → `{ alt: true, key: "k", ... }`. Returns null for empty/garbage
 *  input so callers can treat "hotkeys configured" as `parsed !== null`. */
function parseHotkey(combo: string | undefined | null): ParsedHotkey | null {
  const parts = (combo || "").split("+").map((p) => p.trim().toLowerCase()).filter(Boolean);
  if (!parts.length) return null;
  const result: ParsedHotkey = { ctrl: false, alt: false, shift: false, meta: false, key: "", bare: false };
  for (const part of parts) {
    const mod = HOTKEY_MODIFIER_ALIASES[part];
    if (mod) result[mod] = true;
    else result.key = part === " " ? "space" : part; // last non-modifier token is the trigger key
  }
  if (!result.key) return null;
  result.bare = !result.ctrl && !result.alt && !result.shift && !result.meta;
  return result;
}

/** Normalise a live KeyboardEvent's key the same way parseHotkey does, so the
 *  two sides compare on identical tokens (browsers report the space bar's
 *  `.key` as a literal " " rather than the word "space"). */
function eventKeyToken(e: KeyboardEvent): string {
  const k = e.key.toLowerCase();
  return k === " " ? "space" : k;
}

function matchesHotkey(e: KeyboardEvent, parsed: ParsedHotkey | null): boolean {
  if (!parsed || e.repeat) return false;
  if (e.ctrlKey !== parsed.ctrl) return false;
  if (e.altKey !== parsed.alt) return false;
  if (e.shiftKey !== parsed.shift) return false;
  if (e.metaKey !== parsed.meta) return false;
  return eventKeyToken(e) === parsed.key;
}

/** A bare (no-modifier) hotkey must not fire while the visitor is typing on
 *  the host page — otherwise typing the letter "k" into any form on the site
 *  would silently open a voice call. Modifier combos are exempt (same
 *  convention as most apps' Ctrl/Cmd shortcuts): nobody types Alt+K into a
 *  text field expecting a literal "k". */
function isEditableTarget(target: EventTarget | null): boolean {
  const el = target as HTMLElement | null;
  if (!el) return false;
  const tag = el.tagName;
  return tag === "INPUT" || tag === "TEXTAREA" || !!el.isContentEditable;
}

const HOTKEY_DISPLAY: Record<string, string> = {
  ctrl: "Ctrl", control: "Ctrl",
  alt: "Alt", option: "Alt",
  shift: "Shift",
  meta: "Cmd", cmd: "Cmd", command: "Cmd", win: "Win", windows: "Win",
  escape: "Esc", esc: "Esc",
  space: "Space", " ": "Space",
};

/** `"alt+k"` → `"Alt+K"`, `"meta+j"` → `"Cmd+J"` — for the one-time hint only;
 *  never used for matching. */
function formatHotkey(combo: string): string {
  return combo
    .split("+")
    .map((p) => p.trim().toLowerCase())
    .filter(Boolean)
    .map((p) => HOTKEY_DISPLAY[p] || (p.length === 1 ? p.toUpperCase() : p.charAt(0).toUpperCase() + p.slice(1)))
    .join("+");
}

const HOTKEY_HINT_SEEN_PREFIX = "voxide_hotkey_hint_seen_";

/** Same per-key scoping as VoxideClient's UI cache — different sites (and
 *  therefore different hotkeys) never share this flag. */
function hasSeenHotkeyHint(publicKey: string): boolean {
  if (typeof window === "undefined") return true; // SSR: never show
  try {
    return window.localStorage.getItem(HOTKEY_HINT_SEEN_PREFIX + publicKey.slice(-12)) === "1";
  } catch {
    return true; // storage blocked (private mode, locked-down settings) — don't nag every load
  }
}

function markHotkeyHintSeen(publicKey: string): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(HOTKEY_HINT_SEEN_PREFIX + publicKey.slice(-12), "1");
  } catch {
    /* quota/private mode — worst case the hint reappears next visit */
  }
}

