interface Palette {
  panelBg: string; panelBorder: string; bodyBg: string;
  aiBubbleBg: string; aiBubbleBorder: string; aiBubbleText: string;
  inputBg: string; inputText: string; muted: string;
  toggleTrack: string; toggleActiveBg: string; toggleActiveText: string; toggleIdleText: string;
  chip: string; chipText: string; scrollbar: string; shadow: string;
}

function buildPalette(dark: boolean): Palette {
  if (dark) {
    return {
      panelBg: "#0f1115", panelBorder: "#23262d", bodyBg: "#0b0d10",
      aiBubbleBg: "#1a1d23", aiBubbleBorder: "#262a31", aiBubbleText: "#e6e8eb",
      inputBg: "#1a1d23", inputText: "#e6e8eb", muted: "#8b9096",
      toggleTrack: "#22262d", toggleActiveBg: "#0f1115", toggleActiveText: "#fff", toggleIdleText: "#8b9096",
      chip: "#181b20", chipText: "#c7ccd1", scrollbar: "#3a3f47",
      shadow: "0 25px 50px -12px rgba(0,0,0,0.6), 0 0 0 1px rgba(255,255,255,0.04)",
    };
  }
  return {
    panelBg: "#fff", panelBorder: "#e5e7eb", bodyBg: "#f9fafb",
    aiBubbleBg: "#fff", aiBubbleBorder: "#f0f1f3", aiBubbleText: "#1f2937",
    inputBg: "#f3f4f6", inputText: "#1f2937", muted: "#9ca3af",
    toggleTrack: "#e5e7eb", toggleActiveBg: "#fff", toggleActiveText: "#111827", toggleIdleText: "#6b7280",
    chip: "#fff", chipText: "#374151", scrollbar: "#d1d5db",
    shadow: "0 25px 50px -12px rgba(0,0,0,0.25), 0 0 0 1px rgba(0,0,0,0.05)",
  };
}

function onAccent(hex: string): string {
  const h = (hex || "").replace("#", "");
  if (h.length !== 6) return "#ffffff";
  const r = parseInt(h.slice(0, 2), 16) / 255, g = parseInt(h.slice(2, 4), 16) / 255, b = parseInt(h.slice(4, 6), 16) / 255;
  return 0.2126 * r + 0.7152 * g + 0.0722 * b > 0.62 ? "#111827" : "#ffffff";
}

function useResolvedDark(theme: VoxideTheme): boolean {
  const [dark, setDark] = useState<boolean>(() => {
    if (theme === "dark") return true;
    if (theme === "light") return false;
    if (typeof window !== "undefined" && window.matchMedia) return window.matchMedia("(prefers-color-scheme: dark)").matches;
    return false;
  });
  useEffect(() => {
    if (theme !== "auto") { setDark(theme === "dark"); return; }
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const onChange = () => setDark(mq.matches);
    onChange();
    mq.addEventListener?.("change", onChange);
    return () => mq.removeEventListener?.("change", onChange);
  }, [theme]);
  return dark;
}

/** Built-in semantic colours for each live state. */
export /** Short words for each live state, for the voice bar's optional label.
 *  Kept to one or two words: the bar is small and a long label makes the pill
 *  jump in width every time the agent changes what it is doing. */
const STATUS_TEXT: Record<VoxideStatus, string> = {
  idle: "",
  armed: "Ready",
  connecting: "Connecting",
  listening: "Listening",
  thinking: "Thinking",
  speaking: "Speaking",
  executing: "Working",
  error: "Something went wrong",
};

const DEFAULT_STATUS_COLORS: Required<VoxideStatusColors> = {
  listening: "#10b981",
  speaking: "#a855f7",
  thinking: "#3b82f6",
  executing: "#f97316",
  error: "#ef4444",
  connecting: "#eab308",
};

/**
 * Resolve the colour for the current state.
 *
 * `mode` lets a developer stop the widget cycling through semantic colours
 * that clash with their brand: "brand" paints every activity state with the
 * accent instead. Errors deliberately stay red even then — a failed call is
 * not a brand moment, and washing it in the accent would hide it.
 */
function statusColor(
  status: VoxideStatus,
  accent: string,
  mode: VoxideStatusColorMode = "status",
  custom?: VoxideStatusColors,
): string {
  const key = status as keyof VoxideStatusColors;
  const fallback = DEFAULT_STATUS_COLORS[key];
  if (!fallback) return accent; // idle / armed — always the brand colour

  if (mode === "custom") return custom?.[key] || fallback;
  if (mode === "brand") return status === "error" ? fallback : accent;
  return fallback;
}

function VoiceWave({ status, accent, wakePhrase, colorMode, customColors }: { status: VoxideStatus; accent: string; wakePhrase?: string | null; colorMode?: VoxideStatusColorMode; customColors?: VoxideStatusColors }) {
  const active = status === "listening" || status === "speaking" || status === "thinking";
  const color = statusColor(status, accent, colorMode, customColors);
  const label =
    status === "speaking" ? "Speaking…" : status === "thinking" ? "Thinking…" :
    status === "executing" ? "Working…" : status === "listening" ? "Listening…" :
    status === "connecting" ? "Connecting…" : status === "error" ? "Connection error" :
    status === "armed" && wakePhrase ? `Say “${wakePhrase}” or tap the mic` : "Tap the mic to start";
  const bars = [0, 120, 60, 180, 30];
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 24, padding: "32px 16px" }}>
      <div style={{ width: 132, height: 132, borderRadius: "50%", background: `radial-gradient(circle at 30% 30%, ${color}33, ${color}11 70%)`, border: `1px solid ${color}55`, display: "flex", alignItems: "center", justifyContent: "center", animation: active ? "vx-orb 2.4s ease-in-out infinite" : "none" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 6, height: 56 }}>
          {bars.map((delay, i) => (
            <span key={i} style={{ display: "inline-block", width: 6, height: 56, borderRadius: 3, backgroundColor: color, transformOrigin: "center", animation: active ? `vx-wave 0.9s ease-in-out ${delay}ms infinite` : "none", opacity: active ? 1 : 0.35 }} />
          ))}
        </div>
      </div>
      <div style={{ fontSize: 13, fontWeight: 600, letterSpacing: "0.02em", opacity: 0.75 }}>{label}</div>
    </div>
  );
}

/**
 * The "Jexi" launcher visual for launcherMode="voice-orb": no panel ever
 * opens, so the launcher button itself must read as a living orb. Runs its
 * own requestAnimationFrame loop reading real mic/agent audio levels and
 * mutates DOM styles directly — no React state, no re-rendering the rest of
 * the widget 60 times a second. Glow uses box-shadow (never clipped by the
 * button's own overflow/border-radius); the inner highlight is a plain child
 * div sized to the button so it's naturally clipped to its shape.
 */
function OrbCore({
  status, accent, targetRef, getInputLevel, getOutputLevel, colorMode, customColors,
}: {
  status: VoxideStatus;
  accent: string;
  targetRef: React.RefObject<HTMLButtonElement | null>;
  getInputLevel: () => number;
  getOutputLevel: () => number;
  colorMode?: VoxideStatusColorMode;
  customColors?: VoxideStatusColors;
}) {
  const coreRef = useRef<HTMLDivElement>(null);
  const smoothedRef = useRef(0);
  const color = statusColor(status, accent, colorMode, customColors);

  useEffect(() => {
    // Snapshot the current node once — the ongoing loop and the cleanup both
    // target this same element, rather than re-reading a ref that could have
    // moved on by the time cleanup runs.
    const btn = targetRef.current;
    let raf = 0;
    const t0 = performance.now();
    const tick = (t: number) => {
      let target: number;
      if (status === "speaking") target = getOutputLevel();
      else if (status === "listening") target = getInputLevel();
      else target = 0.35 + 0.25 * Math.sin((t - t0) / 450); // connecting/thinking/executing: gentle breathing

      // Exponential smoothing — raw per-frame RMS is jittery; this reads as a
      // natural pulse instead of a nervous flicker.
      smoothedRef.current += (target - smoothedRef.current) * 0.22;
      const level = Math.max(0, Math.min(1, smoothedRef.current));

      if (btn) {
        const blur = 10 + level * 26;
        const spread = 4 + level * 20;
        btn.style.boxShadow = `0 10px 25px -5px rgba(0,0,0,0.3), 0 0 ${blur}px ${spread}px ${color}`;
      }
      if (coreRef.current) {
        coreRef.current.style.transform = `scale(${1 + level * 0.16})`;
        coreRef.current.style.opacity = String(0.7 + level * 0.3);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      if (btn) btn.style.boxShadow = "";
    };
  }, [status, accent, color, getInputLevel, getOutputLevel, targetRef]);

  return (
    <div
      ref={coreRef}
      style={{ position: "absolute", inset: 0, borderRadius: "inherit", background: `radial-gradient(circle at 35% 30%, ${color} 0%, ${color}00 72%)`, pointerEvents: "none" }}
    />
  );
}

const WAVE_BARS = 5;

/**
 * The live waveform inside launcherMode="voice-bar".
 *
 * Same discipline as OrbCore: one requestAnimationFrame loop mutating DOM
 * styles directly, never React state — a widget embedded on someone else's
 * page must not re-render itself 60 times a second.
 *
 * Each bar gets its own phase offset so the row reads as a travelling wave
 * rather than five bars moving as one block, which is what makes it feel like
 * speech rather than a progress indicator.
 */
function VoiceBarWave({
  status, active, getInputLevel, getOutputLevel,
}: {
  status: VoxideStatus;
  active: boolean;
  getInputLevel: () => number;
  getOutputLevel: () => number;
}) {
  const barsRef = useRef<(HTMLSpanElement | null)[]>([]);
  const smoothedRef = useRef(0);

  useEffect(() => {
    let raf = 0;
    const t0 = performance.now();
    const tick = (t: number) => {
      let target: number;
      if (!active) target = 0; // idle: bars rest at their floor height
      else if (status === "speaking") target = getOutputLevel();
      else if (status === "listening") target = getInputLevel();
      else target = 0.3 + 0.2 * Math.sin((t - t0) / 420); // connecting/thinking/executing

      smoothedRef.current += (target - smoothedRef.current) * 0.25;
      const level = Math.max(0, Math.min(1, smoothedRef.current));

      for (let i = 0; i < barsRef.current.length; i++) {
        const el = barsRef.current[i];
        if (!el) continue;
        const phase = Math.sin((t - t0) / 170 + i * 0.85);
        const h = 0.2 + level * (0.8 + 0.3 * phase);
        el.style.transform = `scaleY(${Math.max(0.16, Math.min(1, h))})`;
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [status, active, getInputLevel, getOutputLevel]);

  return (
    <span aria-hidden style={{ display: "flex", alignItems: "center", gap: 3, height: 16 }}>
      {Array.from({ length: WAVE_BARS }).map((_, i) => (
        <span
          key={i}
          ref={(el) => { barsRef.current[i] = el; }}
          style={{
            display: "block", width: 3, height: 16, borderRadius: 999,
            backgroundColor: "currentColor", transformOrigin: "center",
            transform: "scaleY(0.16)",
          }}
        />
      ))}
    </span>
  );
}

/**
 * End-of-conversation rating. Deliberately progressive: stars first, and the
 * comment box only appears once a rating is picked, so the cheapest possible
 * answer (one tap) is always enough and nobody is confronted with a form.
 *
 * Renders above whichever launcher is in use, so it works identically in
 * panel, orb and bar modes.
 */
function FeedbackPrompt({
  accent, P, corner, prompt, commentPlaceholder, thanks, align, onSubmit, onDismiss,
}: {
  accent: string;
  P: Palette;
  corner: number;
  prompt: string;
  commentPlaceholder: string;
  thanks: string;
  align: "flex-start" | "center" | "flex-end";
  onSubmit: (rating: number, comment?: string) => Promise<boolean> | void;
  onDismiss: () => void;
}) {
  const [rating, setRating] = useState(0);
  const [hover, setHover] = useState(0);
  const [comment, setComment] = useState("");
  const [sent, setSent] = useState(false);
  const [busy, setBusy] = useState(false);
  // Never claim a rating was recorded when the request didn't succeed. Silently
  // showing "Thanks!" over a failed POST is worse than an error: the visitor
  // believes they were heard, and the developer sees nothing in their
  // dashboard with no clue why.
  const [failed, setFailed] = useState(false);

  // Auto-close shortly after the thank-you so the visitor's page is handed back
  // to them without another click.
  useEffect(() => {
    if (!sent) return;
    const id = setTimeout(onDismiss, 1600);
    return () => clearTimeout(id);
  }, [sent, onDismiss]);

  // Record the star the moment it's tapped. Waiting for "Send" loses the
  // rating entirely whenever someone taps a star and then closes the prompt or
  // walks away — which is the common case, since a comment is optional and
  // most people don't write one. The server upserts, so the later "Send" (if
  // it comes) updates this same row with the comment.
  const pick = (n: number) => {
    setRating(n);
    setFailed(false);
    void Promise.resolve(onSubmit(n)).then((ok) => { if (ok === false) setFailed(true); });
  };

  const send = async () => {
    if (!rating || busy) return;
    setBusy(true);
    setFailed(false);
    const ok = await onSubmit(rating, comment);
    setBusy(false);
    if (ok === false) setFailed(true);
    else setSent(true);
  };

  const shown = hover || rating;

  return (
    <motion.div
      initial={{ opacity: 0, y: 10, scale: 0.96 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, y: 6, scale: 0.96 }}
      transition={{ type: "spring", stiffness: 320, damping: 26 }}
      role="dialog"
      aria-label="Rate this conversation"
      style={{
        marginBottom: 12, width: 268, alignSelf: align,
        background: P.panelBg, border: `1px solid ${P.panelBorder}`,
        borderRadius: corner, boxShadow: P.shadow, padding: 14,
        color: P.aiBubbleText,
      }}
    >
      {sent ? (
        <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, fontWeight: 600, padding: "4px 0" }}>
          <Star style={{ width: 16, height: 16, fill: accent, color: accent }} />
          <span>{thanks}</span>
        </div>
      ) : (
        <>
          <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 8, marginBottom: 10 }}>
            <span style={{ fontSize: 13, fontWeight: 600, lineHeight: 1.35 }}>{prompt}</span>
            <button
              type="button" onClick={onDismiss} aria-label="Dismiss"
              style={{ border: "none", background: "transparent", color: P.muted, cursor: "pointer", display: "flex", padding: 0, flexShrink: 0 }}
            >
              <X style={{ width: 14, height: 14 }} />
            </button>
          </div>

          <div style={{ display: "flex", gap: 4, marginBottom: rating ? 10 : 0 }} onMouseLeave={() => setHover(0)}>
            {[1, 2, 3, 4, 5].map((n) => (
              <button
                key={n} type="button"
                onClick={() => pick(n)}
                onMouseEnter={() => setHover(n)}
                aria-label={`${n} star${n > 1 ? "s" : ""}`}
                style={{ border: "none", background: "transparent", cursor: "pointer", padding: 2, display: "flex", lineHeight: 0 }}
              >
                <Star
                  style={{
                    width: 24, height: 24, transition: "transform .12s ease",
                    transform: hover === n ? "scale(1.15)" : "scale(1)",
                    fill: n <= shown ? accent : "transparent",
                    color: n <= shown ? accent : P.muted,
                  }}
                />
              </button>
            ))}
          </div>

          <AnimatePresence>
            {rating > 0 && (
              <motion.div
                initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }} exit={{ opacity: 0, height: 0 }}
                style={{ overflow: "hidden" }}
              >
                {/* The star is recorded on tap, so say so — otherwise "Done"
                    reads as "discard my rating". Downgraded to a neutral
                    prompt if that request actually failed. */}
                <div style={{ fontSize: 11, color: failed ? "#ef4444" : P.muted, marginBottom: 6 }}>
                  {failed
                    ? "Couldn't save that — check your connection and try again."
                    : "Rating saved. Want to add anything?"}
                </div>
                <textarea
                  value={comment}
                  onChange={(e) => setComment(e.target.value.slice(0, 2000))}
                  placeholder={commentPlaceholder}
                  rows={2}
                  style={{
                    width: "100%", boxSizing: "border-box", resize: "none",
                    background: P.inputBg, color: P.inputText,
                    border: `1px solid ${P.panelBorder}`, borderRadius: Math.max(8, corner - 6),
                    padding: "8px 10px", fontSize: 13, outline: "none", fontFamily: "inherit",
                  }}
                />
                <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                  <button
                    type="button" onClick={send} disabled={busy}
                    style={{
                      flex: 1, height: 34, borderRadius: Math.max(8, corner - 6), border: "none",
                      background: accent, color: onAccent(accent), fontSize: 13, fontWeight: 700,
                      cursor: busy ? "default" : "pointer", opacity: busy ? 0.7 : 1,
                      display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
                    }}
                  >
                    {busy && <Loader2 className="vx-spin" style={{ width: 14, height: 14 }} />}
                    {busy ? "Sending…" : failed ? "Try again" : "Send"}
                  </button>
                  <button
                    type="button" onClick={onDismiss}
                    style={{
                      height: 34, padding: "0 12px", borderRadius: Math.max(8, corner - 6),
                      border: `1px solid ${P.panelBorder}`, background: "transparent",
                      color: P.muted, fontSize: 13, fontWeight: 600, cursor: "pointer",
                    }}
                  >
                    Done
                  </button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </>
      )}
      {!sent && !rating && (
        <div style={{ fontSize: 11, color: P.muted, marginTop: 8 }}>
          Tap a star — a comment is optional.
        </div>
      )}
    </motion.div>
  );
}

export interface VoxideWidgetProps {
  client: VoxideClient;
  accentColor?: string;
  avatarUrl?: string;
  position?: VoxidePosition;
  theme?: VoxideTheme;
  title?: string;
  defaultOpen?: boolean;
}

export function VoxideWidget({ client, accentColor, avatarUrl, position, theme, title, defaultOpen }: VoxideWidgetProps) {
  const ui = (client?.ui || {}) as VoxideAppearance & { defaultOpen?: boolean };

  // Resolve the full config (props → dashboard/ui → defaults).
  const accent = accentColor || ui.accentColor || DEFAULT_ACCENT;
  const avatar = avatarUrl || ui.avatarUrl || "";
  const launcherModeResolved: VoxideLauncherMode = ui.launcherMode || "panel";
  // The bar is a bottom-edge element by design — it reads as part of the page
  // rather than a corner attachment — so it centres unless told otherwise.
  const dock: VoxidePosition =
    position || ui.position || (launcherModeResolved === "voice-bar" ? "bottom-center" : "bottom-right");
  const resolvedTheme: VoxideTheme = theme || ui.theme || "auto";
  const launcherShape: VoxideLauncherShape = ui.launcherShape || "circle";
  const launcherSize: VoxideLauncherSize = ui.launcherSize || "md";
  const launcherIcon: VoxideLauncherIcon = ui.launcherIcon || "chat";
  const launcherLabel = ui.launcherLabel || "";
  const corner: VoxideCorner = ui.cornerRadius || "rounded";
  const headerStyle: VoxideHeaderStyle = ui.headerStyle || "gradient";
  const skin: VoxideSkin = ui.skin || "solid";
  const statusColorMode: VoxideStatusColorMode = ui.statusColorMode || "status";
  const statusColors: VoxideStatusColors | undefined = ui.statusColors;
  const launcherMode: VoxideLauncherMode = launcherModeResolved;
  // What paints the live audio. "wave" is the DOM waveform that has always
  // shipped and stays the default; "orb" swaps in a WebGPU sphere and silently
  // reverts to "wave" wherever WebGPU cannot run (see orbFailed below).
  const visualizer: VoxideVisualizer = ui.visualizer || "wave";
  const orbConfig: VoxideOrbConfig | undefined = ui.orb;
  // Words alongside the orb in the voice bar. Off unless asked for.
  const showStatusText = ui.showStatusText === true;
  const feedbackEnabled = ui.feedbackEnabled !== false;
  const feedbackPrompt = ui.feedbackPrompt || "How did that go?";
  const feedbackCommentPlaceholder = ui.feedbackCommentPlaceholder || "Anything you'd like to add? (optional)";
  const feedbackThanks = ui.feedbackThanks || "Thanks for the feedback!";
  const subtitle = ui.subtitle || "";
  const greeting = ui.greeting || "";
  const placeholder = ui.placeholder || "Type a message…";
  const starters = ui.starters || [];
  const showBranding = ui.showBranding !== false;
  const usageLimitMessage = ui.usageLimitMessage || DEFAULT_USAGE_LIMIT_MESSAGE;
  const showModeToggle = ui.showModeToggle !== false;
  const initialMode: VoxideMode = ui.defaultMode === "voice" ? "voice" : "text";
  const autoOpenDelay = ui.autoOpenDelay || 0;
  // Parsed once per distinct combo string, not per render — matchesHotkey()
  // runs on every keydown anywhere on the host page, so this stays cheap.
  const parsedHotkeyActivate = useMemo(() => parseHotkey(ui.hotkeyActivate), [ui.hotkeyActivate]);
  const parsedHotkeyDeactivate = useMemo(
    // No separate deactivate combo configured → the activate combo toggles.
    () => parseHotkey(ui.hotkeyDeactivate) || parsedHotkeyActivate,
    [ui.hotkeyDeactivate, parsedHotkeyActivate]
  );

  const dark = useResolvedDark(resolvedTheme);
  const P = useMemo(() => buildPalette(dark), [dark]);
  const txt = onAccent(accent);
  const cornerPx = CORNER_PX[corner];
  const bubbleR = BUBBLE_PX[corner];
  const fabPx = LAUNCHER_PX[launcherSize];
  const LauncherIcon = LAUNCHER_ICONS[launcherIcon] || MessageSquare;
  // Glass = translucent + frosted blur ("foggy"). Noise = the site's own grain
  // texture, for developers whose brand is matte/textured rather than glossy.
  const panelBg = skin === "glass" ? hexToRgba(P.panelBg, dark ? 0.6 : 0.72) : P.panelBg;
  const panelBackdrop = skin === "glass" ? "blur(20px) saturate(160%)" : undefined;

  const [isOpen, setIsOpen] = useState(!!(defaultOpen ?? ui.defaultOpen));
  const [inputText, setInputText] = useState("");
  const [mode, setMode] = useState<VoxideMode>(initialMode);
  const [showLabel, setShowLabel] = useState(false);
  const [showLimitBubble, setShowLimitBubble] = useState(false);
  // One-time onboarding hint for the hotkey feature — see the effect below
  // that arms it and the localStorage helpers above that make it permanent
  // (never shown again on this browser once it's been shown once).
  const [showHotkeyHint, setShowHotkeyHint] = useState(false);
  const [initState, setInitState] = useState<"pending" | "ready" | "error">(client?.isInitialized ? "ready" : "pending");
  const [initError, setInitError] = useState<string | null>(null);
  const [initErrorCode, setInitErrorCode] = useState<string | undefined>(undefined);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const launcherBtnRef = useRef<HTMLButtonElement>(null);

  // Whether the widget's shape is known well enough to paint. False only on a
  // visitor's very first load with nothing cached; see `uiHydrated`.
  const [uiReady, setUiReady] = useState(!!client?.uiHydrated);

  // Self-initialise.
  useEffect(() => {
    if (!client || client.isInitialized) {
      if (client?.isInitialized) { setInitState("ready"); setUiReady(true); }
      return;
    }
    let cancelled = false;
    client.init().then(() => { if (!cancelled) { setInitState("ready"); setUiReady(true); } }).catch((err: any) => {
      if (cancelled) return;
      setInitError(err?.message || "Initialization failed.");
      setInitErrorCode(err?.code);
      setInitState("error");
      // Show the widget anyway on failure — the error/usage-limit message is
      // the whole point of rendering at that stage, and hiding forever would
      // turn a recoverable network blip into a silently missing widget.
      setUiReady(true);
    });
    // Safety net for a backend that never answers at all — deliberately long.
    //
    // Anything shorter re-creates the bug this gating exists to kill: a cold
    // backend can take ~4s, so a 2.5s failsafe would paint the DEFAULT corner
    // bubble and then visibly morph into the real widget a second later. Being
    // absent a moment longer is strictly better than being wrong on screen, so
    // this only fires when init is genuinely broken — at which point painting
    // the default is right, because that's how the error state gets shown.
    // Repeat visits read the appearance cache and never reach this path.
    const failsafe = setTimeout(() => { if (!cancelled) setUiReady(true); }, 8000);

    return () => { cancelled = true; clearTimeout(failsafe); };
  }, [client]);

  const {
    status, messages, currentAction, errorCode: voiceErrorCode, connect, disconnect, sendText, getInputLevel, getOutputLevel,
    wakeAvailable, wakeArmed, wakeFailure, wakePhrase, wakeAutoArm, armWakeWord, disarmWakeWord,
    endedSession, submitFeedback, dismissFeedback,
  } = useVoxideVoice(client);

  // A rating is only ever asked for after a real exchange (the client sets
  // endedSession only then), and never while the panel is still open — the
  // conversation isn't over from the visitor's point of view until it's gone.
  const showFeedback = feedbackEnabled && !!endedSession && !isOpen;
  // A usage_limit rejection can happen either before the widget ever connects
  // (init() itself is blocked) or mid-session on the WS (the account was fine
  // at page load but ran out while connecting a call) — both get the same
  // friendly treatment instead of a generic "Connection error".
  const isUsageLimitBlocked = (initState === "error" && initErrorCode === "usage_limit") || (status === "error" && voiceErrorCode === "usage_limit");

  useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages, status, currentAction]);
  // Closing the panel hangs up an active call. Only applies to launcherMode
  // "panel" — in "voice-orb" mode isOpen never becomes true at all, and the
  // click handler manages connect/disconnect directly.
  useEffect(() => {
    // Deliberately keyed off a live session, not merely "not idle" — closing
    // the panel while only the wake listener is running must leave it running,
    // and calling disconnect() there would bounce through a needless re-arm.
    const sessionLive = status !== "idle" && status !== "error" && status !== "armed";
    if (launcherMode === "panel" && !isOpen && sessionLive) disconnect();
  }, [launcherMode, isOpen, status, disconnect]);
  useEffect(() => {
    const onBeforeUnload = () => {
      try {
        // Flag first: this teardown is the page dying, not a finished
        // conversation, so it must not raise the end-of-call rating prompt.
        if (client) client._unloading = true;
        disconnect();
      } catch {}
    };
    window.addEventListener("beforeunload", onBeforeUnload);
    return () => window.removeEventListener("beforeunload", onBeforeUnload);
  }, [disconnect, client]);

  // Launcher label reveal + auto-open.
  useEffect(() => {
    if (!launcherLabel || isOpen) return;
    const t = setTimeout(() => setShowLabel(true), 1200);
    return () => clearTimeout(t);
  }, [launcherLabel, isOpen]);

  // Hotkey onboarding hint: shown once ever per browser per site (see
  // hasSeenHotkeyHint/markHotkeyHintSeen above), the same reveal delay as the
  // launcher label so it doesn't compete with the very first paint. Marking
  // it seen happens right as it's shown, not on dismiss — so a visitor who
  // navigates away or closes the tab in that first second still doesn't get
  // it twice, and it genuinely never reappears once shown.
  useEffect(() => {
    if (!parsedHotkeyActivate || !client?.publicKey || isOpen) return;
    if (hasSeenHotkeyHint(client.publicKey)) return;
    const t = setTimeout(() => {
      setShowHotkeyHint(true);
      markHotkeyHintSeen(client.publicKey);
    }, 1200);
    return () => clearTimeout(t);
  }, [parsedHotkeyActivate, client, isOpen]);
  useEffect(() => {
    if (autoOpenDelay <= 0) return;
    const t = setTimeout(() => setIsOpen(true), autoOpenDelay);
    return () => clearTimeout(t);
  }, [autoOpenDelay]);

  // Arm the wake listener once the client is ready. Runs once per mount: the
  // client re-arms itself after each conversation, so repeating that here would
  // fight it — and would also re-arm right after a visitor deliberately
  // switched it off.
  const autoArmedRef = useRef(false);
  useEffect(() => {
    if (autoArmedRef.current) return;
    if (initState !== "ready" || !wakeAvailable || !wakeAutoArm) return;
    autoArmedRef.current = true;
    armWakeWord();
  }, [initState, wakeAvailable, wakeAutoArm, armWakeWord]);

  // If the panel opens in voice mode, connect immediately.
  useEffect(() => {
    const startable = status === "idle" || status === "error" || status === "armed";
    if (isOpen && mode === "voice" && startable && initState === "ready") connect();
  }, [isOpen, mode, initState]); // eslint-disable-line react-hooks/exhaustive-deps

  const inputsDisabled = initState !== "ready";
  // "armed" is NOT an active session — the wake listener is running locally,
  // but no call is open and nothing is billed. Treating it as active would
  // paint the launcher as live and turn a click into a hang-up.
  const voiceActive = status !== "idle" && status !== "error" && status !== "armed";
  /** Every state a click should start a conversation from. */
  const canStartVoice = status === "idle" || status === "error" || status === "armed";
  const sColor = statusColor(status, accent, statusColorMode, statusColors);

  // The orb's two-step fallback. `orbFailed` latches on any reason WebGPU
  // could not run — no adapter, a compile error, a lost device mid-call — and
  // never unlatches, so the widget settles on the waveform instead of thrashing
  // between the two. `orbLive` gates the swap the other way: the waveform stays
  // up until the orb has actually painted a frame, so there is never a gap.
  const [orbFailed, setOrbFailed] = useState(false);
  const [orbLive, setOrbLive] = useState(false);
  const orbEnabled = visualizer === "orb" && !orbFailed && launcherMode !== "panel";
  const showOrb = orbEnabled && orbLive;
  /** The orb has replaced the round launcher's own fill, border and shadow. */
  const orbTakesOver = showOrb && launcherMode === "voice-orb" && !isOpen;

  const handleOrbUnavailable = React.useCallback((reason: string) => {
    // Not an error the developer needs to act on: the fallback is the shipped
    // waveform and the visitor sees a working widget either way.
    if (typeof console !== "undefined") {
      console.info(`[Voxide] Orb visualizer unavailable, using the waveform. ${reason}`);
    }
    setOrbLive(false);
    setOrbFailed(true);
  }, []);

  // Both edges matter. On unmount the orb reports false, so a remount cannot
  // leave the widget believing a blank canvas is still painting, which in
  // voice-orb mode strips the launcher's fill, border and icon and would show
  // nothing at all while the new device comes up.
  const handleOrbLiveChange = React.useCallback((live: boolean) => setOrbLive(live), []);

  // A prop beats both the dashboard and the constructor `ui`, and it does it
  // without going anywhere near VoxideClient, so the warning there cannot see
  // it. This is the path that actually bit: `position="bottom-right"` on this
  // component made the Appearance tab's placement control look dead, on two
  // separate sites, with nothing reported anywhere.
  //
  // Fires once per mount, and only once the dashboard config has landed, or it
  // would compare against defaults and cry wolf on every page.
  const shadowWarned = useRef(false);
  useEffect(() => {
    if (shadowWarned.current || !client?.uiHydrated) return;
    shadowWarned.current = true;
    const remote = (client?.ui || {}) as Record<string, unknown>;
    const props: Record<string, unknown> = { accentColor, avatarUrl, position, theme, title };
    for (const [key, value] of Object.entries(props)) {
      if (value === undefined) continue;
      if (remote[key] === undefined || remote[key] === value) continue;
      console.warn(
        `[Voxide] <VoxideWidget ${key}="${String(value)}"> overrides the dashboard's ` +
          `${key} (${JSON.stringify(remote[key])}). Remove the prop to control it from ` +
          `the Appearance tab.`,
      );
    }
  }, [client, client?.uiHydrated, accentColor, avatarUrl, position, theme, title]);

  // Words for the current state, for developers who want the bar to say what
  // it is doing as well as show it. idle carries none on purpose: a resting bar
  // should read as an invitation, and the launcher label already covers that.
  const statusText = voiceActive || status === "armed" ? STATUS_TEXT[status] : "";

  // Positioning differs by launcher mode — the orb fills the round button in
  // "voice-orb" and sits inline where the bars go in "voice-bar" — so the
  // caller supplies the box and this supplies the orb.
  const renderOrb = (style: React.CSSProperties) =>
    orbEnabled ? (
      <OrbCanvas
        status={status}
        config={orbConfig}
        getInputLevel={getInputLevel}
        getOutputLevel={getOutputLevel}
        // In "brand" mode every state is the developer's accent, so tinting
        // toward it would wash the orb into a single colour. Leave it alone.
        statusColor={statusColorMode === "brand" ? null : sColor}
        onUnavailable={handleOrbUnavailable}
        onLiveChange={handleOrbLiveChange}
        style={style}
      />
    ) : null;

  const handleToggleVoice = () => {
    if (inputsDisabled) return;
    if (canStartVoice) connect(); else disconnect();
  };
  const handleModeChange = (next: VoxideMode) => {
    if (next === mode || inputsDisabled) return;
    // Switching to Voice auto-starts a call if none is active. Switching to
    // Text is purely a view change — if a call is already live, the user is
    // going there to read the transcript, not to hang up, so the session
    // (mic, WS) keeps running untouched in the background.
    if (next === "voice" && canStartVoice) connect();
    setMode(next);
  };
  const handleClosePanel = () => {
    // Only hang up a real call — an armed listener survives the panel closing.
    if (voiceActive) { try { disconnect(); } catch {} }
    setIsOpen(false);
  };

  // Hotkey: activate/deactivate a voice session from anywhere on the page,
  // without touching the launcher. Opt-in — nothing is wired up unless a
  // developer sets `ui.hotkeyActivate`. See the ParsedHotkey helpers above for
  // why a bare (no-modifier) combo is suppressed while typing in a field, and
  // the comment on `hotkeyActivate` in types.ts for what a browser page can
  // and can't capture (no true system-wide hotkey, no Fn key).
  useEffect(() => {
    if (!parsedHotkeyActivate) return;
    const onKeyDown = (e: KeyboardEvent) => {
      const editable = isEditableTarget(e.target);

      // Checked first: with no separate deactivate combo, activate === deactivate,
      // and while a call is live that single combo must stop it, not try to
      // start a second one.
      if (voiceActive && matchesHotkey(e, parsedHotkeyDeactivate) && !(parsedHotkeyDeactivate!.bare && editable)) {
        e.preventDefault();
        if (launcherMode === "panel") { try { disconnect(); } catch {} setIsOpen(false); }
        else disconnect();
        return;
      }

      if (matchesHotkey(e, parsedHotkeyActivate) && !(parsedHotkeyActivate!.bare && editable)) {
        if (inputsDisabled) return;
        if (status === "error" && voiceErrorCode === "usage_limit") {
          e.preventDefault();
          setShowLimitBubble(true);
          return;
        }
        if (!canStartVoice) return; // already live and this is a distinct activate combo — no-op
        e.preventDefault();
        setShowLabel(false);
        setShowHotkeyHint(false);
        // Panel mode: hand off to the existing isOpen+mode="voice" effect
        // (above) so there's exactly one code path that calls connect() for
        // that mode, instead of a second one racing it here.
        if (launcherMode === "panel") { setMode("voice"); setIsOpen(true); }
        else connect();
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [
    parsedHotkeyActivate, parsedHotkeyDeactivate, launcherMode,
    status, voiceErrorCode, canStartVoice, voiceActive, inputsDisabled,
    connect, disconnect,
  ]);

  const handleSendText = (e: React.FormEvent) => {
    e.preventDefault();
    if (inputsDisabled || !inputText.trim()) return;
    sendText(inputText);
    setInputText("");
  };
  const sendStarter = (s: string) => { if (!inputsDisabled) sendText(s); };

  const statusLabel =
    status === "connecting" ? "Connecting…" : status === "listening" ? "Listening…" :
    status === "thinking" ? "Thinking…" : status === "speaking" ? "Speaking…" :
    status === "executing" ? `Executing: ${currentAction}` :
    status === "error" && voiceErrorCode === "usage_limit" ? "Session limit reached" :
    status === "error" ? "Connection error" :
    status === "armed" && wakePhrase ? `Say “${wakePhrase}”` :
    subtitle || "Ready";

  const headerTitle = title || ui.title || client?.agentConfig?.agent?.name || "Voxide Assistant";
  const side: React.CSSProperties =
    dock === "bottom-left" ? { left: 24 }
    : dock === "bottom-center" ? { left: "50%", transform: "translateX(-50%)" }
    : { right: 24 };
  const alignItems: "flex-start" | "center" | "flex-end" =
    dock === "bottom-left" ? "flex-start" : dock === "bottom-center" ? "center" : "flex-end";
  // Rounded launchers now share the same radius scale as the panel/bubbles, so
  // "sharp" reads as sharp everywhere at once instead of only on the panel.
  const fabRadius = launcherShape === "circle" ? "50%" : cornerPx;

  // First-ever load with no cached appearance: paint nothing until init()
  // answers. A few hundred ms of absence is far less jarring than showing the
  // wrong launcher in the wrong corner and having it jump. Every subsequent
  // load reads the cache and skips this entirely.
  if (!uiReady) return null;

  return (
    <div className="vx-enter" style={{ position: "fixed", bottom: 24, ...side, zIndex: 2147483647, display: "flex", flexDirection: "column", alignItems, fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif', fontSize: 14, ["--vx-scrollbar" as any]: P.scrollbar }}>
      <style dangerouslySetInnerHTML={{ __html: VX_STYLES }} />

      <AnimatePresence>
        {isOpen && launcherMode === "panel" && (
          <motion.div
            initial={{ opacity: 0, y: 20, scale: 0.95 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 20, scale: 0.95 }} transition={{ duration: 0.2 }}
            style={{ marginBottom: 16, width: 384, maxWidth: "calc(100vw - 48px)", backgroundColor: panelBg, backdropFilter: panelBackdrop, WebkitBackdropFilter: panelBackdrop, borderRadius: cornerPx, boxShadow: P.shadow, border: `1px solid ${P.panelBorder}`, overflow: "hidden", display: "flex", flexDirection: "column", height: 520, maxHeight: "80vh", color: P.aiBubbleText, position: "relative" }}
          >
            {/* Header */}
            <div style={{ background: headerStyle === "gradient" ? `linear-gradient(135deg, ${accent} 0%, ${accent}cc 100%)` : accent, padding: 16, display: "flex", justifyContent: "space-between", alignItems: "center", color: txt, flexShrink: 0 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 12, minWidth: 0 }}>
                {avatar ? <img src={avatar} alt="" style={{ width: 38, height: 38, borderRadius: "50%", objectFit: "cover", border: `2px solid ${txt}66`, flexShrink: 0 }} /> : null}
                <div style={{ minWidth: 0 }}>
                  <p style={{ fontWeight: 700, fontSize: 16, lineHeight: 1.25, margin: 0, color: txt, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{headerTitle}</p>
                  <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 5, backgroundColor: "rgba(0,0,0,0.18)", padding: "2px 8px", borderRadius: 999, width: "fit-content" }}>
                    <span style={{ width: 7, height: 7, borderRadius: "50%", backgroundColor: sColor }} />
                    <span style={{ fontSize: 10, fontWeight: 600, letterSpacing: "0.05em", color: txt, maxWidth: 220, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{statusLabel}</span>
                  </div>
                </div>
              </div>
              <button type="button" onClick={handleClosePanel} aria-label="Close chat" style={{ padding: 6, borderRadius: 8, border: "none", background: "transparent", color: txt, cursor: "pointer", display: "flex" }}>
                <X style={{ width: 20, height: 20 }} />
              </button>
            </div>

            {/* Executing banner */}
            <AnimatePresence>
              {status === "executing" && currentAction && (
                <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} style={{ overflow: "hidden", flexShrink: 0 }}>
                  <div style={{ backgroundColor: dark ? "#2a1a0a" : "#fff7ed", borderBottom: `1px solid ${dark ? "#4a2f14" : "#fed7aa"}`, padding: 12, display: "flex", alignItems: "center", gap: 12 }}>
                    <div style={{ width: 30, height: 30, borderRadius: "50%", backgroundColor: "#f97316", display: "flex", alignItems: "center", justifyContent: "center", color: "#fff", flexShrink: 0 }}><Zap style={{ width: 15, height: 15 }} /></div>
                    <div>
                      <p style={{ fontSize: 11, fontWeight: 700, color: dark ? "#fdba74" : "#9a3412", textTransform: "uppercase", letterSpacing: "0.1em", margin: "0 0 2px" }}>Action Triggered</p>
                      <p style={{ fontSize: 13, fontWeight: 500, color: dark ? "#fed7aa" : "#7c2d12", margin: 0 }}>Running `{currentAction}`…</p>
                    </div>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            {/* Mode toggle */}
            {initState === "ready" && showModeToggle && (
              <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 4, padding: "8px 12px", backgroundColor: P.bodyBg, borderBottom: `1px solid ${P.aiBubbleBorder}`, flexShrink: 0 }}>
                <div style={{ display: "flex", backgroundColor: P.toggleTrack, borderRadius: 999, padding: 3, gap: 2 }}>
                  {(["text", "voice"] as VoxideMode[]).map((m) => {
                    const selected = mode === m;
                    return (
                      <button key={m} type="button" onClick={() => handleModeChange(m)} style={{ border: "none", background: selected ? P.toggleActiveBg : "transparent", color: selected ? P.toggleActiveText : P.toggleIdleText, fontWeight: 600, fontSize: 12, padding: "6px 14px", borderRadius: 999, cursor: "pointer", boxShadow: selected ? "0 1px 2px rgba(0,0,0,0.12)" : "none", textTransform: "capitalize" }}>{m}</button>
                    );
                  })}
                </div>
              </div>
            )}

            {/* Body */}
            <div className="vx-scroll" style={{ flex: 1, overflowY: "auto", padding: 16, display: "flex", flexDirection: "column", gap: 12, backgroundColor: P.bodyBg }}>
              {isUsageLimitBlocked ? (
                <div style={{ margin: "auto", textAlign: "center", color: P.aiBubbleText, display: "flex", flexDirection: "column", alignItems: "center", gap: 10, padding: "0 8px" }}>
                  <BatteryLow style={{ width: 36, height: 36, color: accent }} />
                  <p style={{ margin: 0, fontWeight: 700, fontSize: 14 }}>Taking a quick break</p>
                  <p style={{ margin: 0, fontSize: 12.5, color: P.muted, lineHeight: 1.5, maxWidth: 260 }}>{usageLimitMessage}</p>
                </div>
              ) : initState === "error" ? (
                <div style={{ margin: "auto", textAlign: "center", color: "#ef4444", display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
                  <X style={{ width: 40, height: 40 }} />
                  <p style={{ margin: 0, fontWeight: 600 }}>Assistant unavailable</p>
                  <p style={{ margin: 0, fontSize: 12, color: P.muted }}>{initError || "Could not connect to Voxide."}</p>
                </div>
              ) : null}
              {initState === "pending" && (
                <div style={{ margin: "auto", textAlign: "center", color: P.muted, display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
                  <Loader2 className="vx-spin" style={{ width: 32, height: 32 }} />
                  <p style={{ margin: 0 }}>Connecting…</p>
                </div>
              )}
              {initState === "ready" && mode === "voice" && !isUsageLimitBlocked && <VoiceWave status={status} accent={accent} wakePhrase={wakePhrase} colorMode={statusColorMode} customColors={statusColors} />}

              {initState === "ready" && mode === "text" && messages.length === 0 && (
                <>
                  {greeting ? (
                    <div style={{ display: "flex", justifyContent: "flex-start" }}>
                      <div style={{ maxWidth: "85%", padding: "10px 14px", borderRadius: `${bubbleR}px ${bubbleR}px ${bubbleR}px 4px`, fontSize: 14, lineHeight: 1.45, backgroundColor: P.aiBubbleBg, color: P.aiBubbleText, border: `1px solid ${P.aiBubbleBorder}` }}>{greeting}</div>
                    </div>
                  ) : status === "idle" ? (
                    <div style={{ margin: "auto", textAlign: "center", color: P.muted, display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
                      <MessageSquare style={{ width: 48, height: 48 }} />
                      <p style={{ margin: 0 }}>Type to start, or switch to Voice.</p>
                    </div>
                  ) : null}

                  {starters.length > 0 && (
                    <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: "auto", paddingTop: 8 }}>
                      {starters.slice(0, 4).map((s, i) => (
                        <button key={i} type="button" onClick={() => sendStarter(s)} disabled={inputsDisabled}
                          style={{ background: P.chip, color: P.chipText, border: `1px solid ${P.aiBubbleBorder}`, borderRadius: 999, padding: "7px 12px", fontSize: 12.5, fontWeight: 500, cursor: inputsDisabled ? "default" : "pointer", textAlign: "left" }}>
                          {s}
                        </button>
                      ))}
                    </div>
                  )}
                </>
              )}

              {initState === "ready" && mode === "text" && messages.map((msg, idx) => (
                <motion.div key={idx} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} style={{ display: "flex", justifyContent: msg.role === "user" ? "flex-end" : "flex-start" }}>
                  <div style={msg.role === "user"
                    ? { maxWidth: "85%", padding: "10px 14px", borderRadius: `${bubbleR}px ${bubbleR}px 4px ${bubbleR}px`, fontSize: 14, lineHeight: 1.45, backgroundColor: accent, color: txt }
                    : { maxWidth: "85%", padding: "10px 14px", borderRadius: `${bubbleR}px ${bubbleR}px ${bubbleR}px 4px`, fontSize: 14, lineHeight: 1.45, backgroundColor: P.aiBubbleBg, color: P.aiBubbleText, border: `1px solid ${P.aiBubbleBorder}` }}>
                    {msg.text}
                  </div>
                </motion.div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            {/* Input */}
            <div style={{ padding: 12, backgroundColor: P.panelBg, borderTop: `1px solid ${P.panelBorder}`, flexShrink: 0 }}>
              {mode === "voice" ? (
                <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8, padding: "4px 0" }}>
                  <button type="button" onClick={handleToggleVoice} disabled={inputsDisabled} aria-label={voiceActive ? "Stop voice call" : "Start voice call"} style={{ width: 56, height: 56, borderRadius: "50%", border: "none", cursor: inputsDisabled ? "not-allowed" : "pointer", display: "flex", alignItems: "center", justifyContent: "center", backgroundColor: voiceActive ? "#ef4444" : accent, color: voiceActive ? "#fff" : txt, opacity: inputsDisabled ? 0.5 : 1 }}>
                    {voiceActive ? <MicOff style={{ width: 24, height: 24 }} /> : <Mic style={{ width: 24, height: 24 }} />}
                  </button>
                  {/* The durable home for wake-word control: the launcher bubble
                      only exists while armed, so without this a visitor who
                      switched it off would have no way back on. */}
                  {wakeAvailable && wakePhrase && !voiceActive && (
                    <button type="button" onClick={wakeArmed ? disarmWakeWord : armWakeWord}
                      style={{ border: "none", background: "transparent", color: wakeArmed ? accent : P.muted, cursor: "pointer", display: "flex", alignItems: "center", gap: 5, padding: "2px 6px", fontSize: 11.5, fontWeight: 600 }}>
                      <Ear style={{ width: 13, height: 13 }} />
                      {wakeArmed ? `Listening for “${wakePhrase}”` : `Start on “${wakePhrase}”`}
                    </button>
                  )}
                  {wakeFailure === "permission-denied" && (
                    <span style={{ fontSize: 11, color: P.muted, textAlign: "center", maxWidth: 220, lineHeight: 1.4 }}>
                      Microphone access is blocked, so the wake word can&apos;t listen. Allow it in your browser settings to use it.
                    </span>
                  )}
                </div>
              ) : (
                <form onSubmit={handleSendText} style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <input type="text" value={inputText} onChange={(e) => setInputText(e.target.value)} placeholder={inputsDisabled ? "Connecting…" : placeholder} disabled={inputsDisabled}
                    style={{ flex: 1, backgroundColor: P.inputBg, border: "2px solid transparent", borderRadius: 12, padding: "10px 16px", fontSize: 14, color: P.inputText, outline: "none", minWidth: 0 }}
                    onFocus={(e) => { e.target.style.border = `2px solid ${accent}`; }} onBlur={(e) => { e.target.style.border = "2px solid transparent"; }} />
                  <button type="submit" disabled={inputsDisabled || !inputText.trim()} aria-label="Send message" style={{ padding: 12, borderRadius: 12, border: "none", cursor: !inputsDisabled && inputText.trim() ? "pointer" : "not-allowed", display: "flex", backgroundColor: !inputsDisabled && inputText.trim() ? accent : P.toggleTrack, color: !inputsDisabled && inputText.trim() ? txt : P.muted }}>
                    <Send style={{ width: 20, height: 20 }} />
                  </button>
                </form>
              )}
              {showBranding && (
                <div style={{ textAlign: "center", marginTop: 8, fontSize: 10.5, color: P.muted, display: "flex", alignItems: "center", justifyContent: "center", gap: 4 }}>
                  <Zap style={{ width: 11, height: 11 }} /> Powered by Voxide
                </div>
              )}
            </div>

            {/* Grain texture overlay for skin="noise" — same treatment as the
                Voxide site's own brand texture, offered so a developer's matte/
                textured page doesn't suddenly get a glossy-flat widget dropped on it. */}
            {skin === "noise" && (
              <div style={{ position: "absolute", inset: 0, backgroundImage: NOISE_SVG_URL, opacity: dark ? 0.05 : 0.1, pointerEvents: "none" }} />
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Launcher label bubble — the developer's invite text normally, or (if
          voice-orb mode is clicked while blocked by usage_limit, which would
          otherwise silently do nothing) a note explaining why. */}
      <AnimatePresence>
        {!isOpen && !voiceActive && showLimitBubble ? (
          <motion.div initial={{ opacity: 0, y: 8, scale: 0.9 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, scale: 0.9 }}
            style={{ marginBottom: 12, background: P.panelBg, color: P.aiBubbleText, border: `1px solid ${P.panelBorder}`, borderRadius: 14, padding: "10px 14px", fontSize: 12.5, lineHeight: 1.5, fontWeight: 500, boxShadow: P.shadow, display: "flex", alignItems: "flex-start", gap: 8, maxWidth: 260 }}>
            <BatteryLow style={{ width: 16, height: 16, color: accent, flexShrink: 0, marginTop: 1 }} />
            <span>{usageLimitMessage}</span>
            <button type="button" onClick={() => setShowLimitBubble(false)} aria-label="Dismiss" style={{ border: "none", background: "transparent", color: P.muted, cursor: "pointer", display: "flex", padding: 0, flexShrink: 0 }}><X style={{ width: 14, height: 14 }} /></button>
          </motion.div>
        ) : !isOpen && !voiceActive && showHotkeyHint && parsedHotkeyActivate ? (
          /* One-time-ever hotkey onboarding tip (see the reveal effect above).
             Dismissing it early doesn't "undo" anything — hasSeenHotkeyHint is
             already permanently set the moment this appears — it just hides it
             now instead of waiting for it to time out on its own. */
          <motion.div key="hotkey-hint" initial={{ opacity: 0, y: 8, scale: 0.9 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, scale: 0.9 }}
            style={{ marginBottom: 12, background: P.panelBg, color: P.aiBubbleText, border: `1px solid ${P.panelBorder}`, borderRadius: 14, padding: "10px 14px", fontSize: 13, fontWeight: 500, boxShadow: P.shadow, display: "flex", alignItems: "center", gap: 8, maxWidth: 260 }}>
            <Keyboard style={{ width: 15, height: 15, color: accent, flexShrink: 0 }} />
            <span>
              {ui.hotkeyDeactivate && ui.hotkeyDeactivate.trim().toLowerCase() !== ui.hotkeyActivate!.trim().toLowerCase() ? (
                <>Press <strong style={{ fontWeight: 700 }}>{formatHotkey(ui.hotkeyActivate!)}</strong> to talk, <strong style={{ fontWeight: 700 }}>{formatHotkey(ui.hotkeyDeactivate)}</strong> to stop</>
              ) : (
                <>Press <strong style={{ fontWeight: 700 }}>{formatHotkey(ui.hotkeyActivate!)}</strong> to talk — press again to stop</>
              )}
            </span>
            <button type="button" onClick={() => setShowHotkeyHint(false)} aria-label="Dismiss" style={{ border: "none", background: "transparent", color: P.muted, cursor: "pointer", display: "flex", padding: 0, flexShrink: 0 }}><X style={{ width: 14, height: 14 }} /></button>
          </motion.div>
        ) : !isOpen && !voiceActive && wakeArmed && wakePhrase ? (
          /* Visible for exactly as long as the microphone is being listened to,
             and its close button actually stops the listening rather than just
             hiding the notice — so "no indicator" always means "not listening". */
          <motion.div key="wake" initial={{ opacity: 0, y: 8, scale: 0.9 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, scale: 0.9 }}
            style={{ marginBottom: 12, background: P.panelBg, color: P.aiBubbleText, border: `1px solid ${P.panelBorder}`, borderRadius: 14, padding: "10px 14px", fontSize: 13, fontWeight: 500, boxShadow: P.shadow, display: "flex", alignItems: "center", gap: 8, maxWidth: 260 }}>
            <Ear style={{ width: 15, height: 15, color: accent, flexShrink: 0 }} />
            <span>Say <strong style={{ fontWeight: 700 }}>&ldquo;{wakePhrase}&rdquo;</strong></span>
            <button onClick={disarmWakeWord} aria-label="Stop listening for the wake word" title="Stop listening"
              style={{ border: "none", background: "transparent", color: P.muted, cursor: "pointer", display: "flex", padding: 0, flexShrink: 0 }}>
              <X style={{ width: 14, height: 14 }} />
            </button>
          </motion.div>
        ) : !isOpen && !voiceActive && launcherLabel && showLabel && (
          <motion.div key="label" initial={{ opacity: 0, y: 8, scale: 0.9 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, scale: 0.9 }}
            style={{ marginBottom: 12, background: P.panelBg, color: P.aiBubbleText, border: `1px solid ${P.panelBorder}`, borderRadius: 14, padding: "10px 14px", fontSize: 13, fontWeight: 500, boxShadow: P.shadow, display: "flex", alignItems: "center", gap: 8, maxWidth: 240 }}>
            <span>{launcherLabel}</span>
            <button type="button" onClick={() => setShowLabel(false)} aria-label="Dismiss" style={{ border: "none", background: "transparent", color: P.muted, cursor: "pointer", display: "flex", padding: 0 }}><X style={{ width: 14, height: 14 }} /></button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* End-of-conversation rating. Sits above whichever launcher is in use,
          so it behaves the same in panel, orb and bar modes. */}
      <AnimatePresence>
        {showFeedback && (
          <FeedbackPrompt
            key="feedback"
            accent={accent}
            P={P}
            corner={Math.max(12, cornerPx)}
            prompt={feedbackPrompt}
            commentPlaceholder={feedbackCommentPlaceholder}
            thanks={feedbackThanks}
            align={alignItems}
            onSubmit={submitFeedback}
            onDismiss={dismissFeedback}
          />
        )}
      </AnimatePresence>

      {/* launcherMode="voice-bar": a slim bottom-docked pill instead of a
          corner button. No panel, no text — click to talk, and the pill grows
          slightly and renders a live waveform while the call is running. */}
      {launcherMode === "voice-bar" ? (
        <motion.button
          type="button"
          aria-label={voiceActive ? "End voice conversation" : launcherLabel || "Talk to this page"}
          aria-pressed={voiceActive}
          onClick={() => {
            if (inputsDisabled || (status === "error" && voiceErrorCode === "usage_limit")) {
              setShowLimitBubble(true);
              return;
            }
            handleToggleVoice();
          }}
          className={!voiceActive && !wakeArmed ? "vx-bar-idle" : undefined}
          initial={false}
          animate={{ height: voiceActive ? 44 : 32, paddingLeft: voiceActive ? 18 : 14, paddingRight: voiceActive ? 18 : 14 }}
          transition={{ type: "spring", stiffness: 420, damping: 32 }}
          whileHover={{ scale: 1.04 }}
          whileTap={{ scale: 0.97 }}
          style={{
            display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
            borderRadius: 999, border: "none", cursor: inputsDisabled ? "wait" : "pointer",
            backgroundColor: voiceActive ? sColor : accent,
            color: onAccent(voiceActive ? sColor : accent),
            boxShadow: voiceActive
              ? `0 8px 24px -6px ${hexToRgba(sColor, 0.55)}, 0 2px 8px rgba(0,0,0,0.18)`
              : "0 6px 18px -6px rgba(0,0,0,0.35), 0 2px 6px rgba(0,0,0,0.15)",
            position: "relative", overflow: "hidden", padding: 0, minWidth: voiceActive ? 116 : 92,
          }}
        >
          {skin === "noise" && (
            <span aria-hidden style={{ position: "absolute", inset: 0, backgroundImage: NOISE_SVG_URL, opacity: dark ? 0.08 : 0.14, pointerEvents: "none" }} />
          )}
          {/* The orb takes the place of the bar strip, keeping the Mic icon
              at rest so the pill still reads as "talk to this page". It is
              mounted whenever the orb is enabled, not only once it is live,
              because it has to paint a frame before it can report being live.
              Until then it is transparent and the waveform below shows. */}
          {/* The orb stands where the mic icon stands. It is the agent's face,
              so it takes the identity slot at the head of the bar rather than
              displacing the waveform, which stays and keeps doing its own job
              of showing level. */}
          {orbEnabled && (
            <span
              aria-hidden
              style={{
                position: "relative", flexShrink: 0,
                width: voiceActive ? 26 : 22, height: voiceActive ? 26 : 22,
                transition: "width 220ms ease, height 220ms ease",
              }}
            >
              {renderOrb({ position: "absolute", inset: 0, width: "100%", height: "100%" })}
            </span>
          )}

          {/* Only while the orb is not painting. Once it is, it is the icon. */}
          {!showOrb && !voiceActive && <Mic style={{ width: 14, height: 14, flexShrink: 0 }} />}

          {/* The waveform and the label are two answers to the same question,
              so the bar carries one at a time. Three indicators of one thing in
              a pill this size is clutter, not information.

              The label wins whenever there is a word to show. At idle there is
              none, so the waveform comes back and the pill is never empty. */}
          {showStatusText && statusText ? (
            <span
              style={{
                fontSize: 12, fontWeight: 600, whiteSpace: "nowrap",
                flexShrink: 0, letterSpacing: "-0.01em",
              }}
            >
              {statusText}
            </span>
          ) : (
            <VoiceBarWave
              status={status}
              active={voiceActive}
              getInputLevel={getInputLevel}
              getOutputLevel={getOutputLevel}
            />
          )}
        </motion.button>
      ) : (
      /* Launcher — in launcherMode="voice-orb" this never opens a panel; a
          click just starts/stops a voice session, and the button itself
          becomes the live orb (see OrbCore). */
      <motion.button
        ref={launcherBtnRef}
        type="button"
        aria-label={
          launcherMode === "voice-orb"
            ? voiceActive ? "Stop voice call" : launcherLabel || "Start voice call"
            : isOpen ? "Close chat" : launcherLabel || "Open chat"
        }
        onClick={() => {
          if (launcherMode === "voice-orb") {
            if (inputsDisabled || (status === "error" && voiceErrorCode === "usage_limit")) {
              // Can't start a session — say why instead of silently doing nothing
              // (or retrying a connection that's just going to fail again).
              setShowLimitBubble(true);
              return;
            }
            setShowLabel(false);
            handleToggleVoice();
            return;
          }
          setIsOpen(!isOpen);
          setShowLabel(false);
        }}
        whileHover={{ scale: 1.06 }} whileTap={{ scale: 0.94 }}
        style={{ width: fabPx, height: fabPx, borderRadius: fabRadius, display: "flex", alignItems: "center", justifyContent: "center", color: txt, border: avatar && !isOpen && !orbTakesOver ? `2px solid ${voiceActive ? sColor : accent}` : "none", cursor: "pointer", position: "relative", overflow: "hidden", padding: 0,
          // With the orb live the launcher has no chrome of its own: the sphere
          // is the button. An accent disc behind it would show as a coloured
          // ring around the rim, and a drop shadow would be a shadow cast by a
          // square nobody can see.
          backgroundColor: orbTakesOver ? "transparent" : voiceActive ? sColor : accent,
          boxShadow: orbTakesOver ? "none" : "0 10px 25px -5px rgba(0,0,0,0.3), 0 4px 10px -5px rgba(0,0,0,0.2)",
          flexShrink: 0 }}>
        {skin === "noise" && <span style={{ position: "absolute", inset: 0, borderRadius: "inherit", backgroundImage: NOISE_SVG_URL, opacity: dark ? 0.08 : 0.14, pointerEvents: "none" }} />}
        {voiceActive && launcherMode !== "voice-orb" && <span className="vx-ping" style={{ position: "absolute", inset: 0, borderRadius: fabRadius, backgroundColor: "currentColor", opacity: 0.3, pointerEvents: "none" }} />}
        {/* Wake word armed — a slow halo, never the live-call ping. */}
        {wakeArmed && !voiceActive && (
          <span className="vx-armed" aria-hidden style={{ position: "absolute", inset: -3, borderRadius: "inherit", border: `2px solid ${accent}`, pointerEvents: "none" }} />
        )}
        {/* The GPU orb, when this project has turned it on. Unlike OrbCore it
            renders whether or not a call is running: in "voice-orb" mode the
            launcher IS the agent, so it stays alive and simply idles. The
            renderer drops to 30fps and pauses entirely when the tab is hidden
            or the launcher scrolls out of view. */}
        {launcherMode === "voice-orb" && !isOpen &&
          renderOrb({ position: "absolute", inset: 0, width: "100%", height: "100%", borderRadius: "inherit" })}

        {launcherMode === "voice-orb" && showOrb && !isOpen ? null
          : launcherMode === "voice-orb" && voiceActive ? (
          <OrbCore status={status} accent={accent} targetRef={launcherBtnRef} getInputLevel={getInputLevel} getOutputLevel={getOutputLevel} colorMode={statusColorMode} customColors={statusColors} />
        ) : isOpen ? <X style={{ width: fabPx * 0.42, height: fabPx * 0.42 }} />
          : avatar ? <img src={avatar} alt="" style={{ width: "100%", height: "100%", borderRadius: fabRadius, objectFit: "cover" }} />
          : <LauncherIcon style={{ width: fabPx * 0.42, height: fabPx * 0.42 }} />}
      </motion.button>
      )}
    </div>
  );
}
