// lib/voxide-sdk/useVoxideVoice.ts
//
// Thin React binding over the voice session — the WebSocket, audio graph, and
// transcript actually live on the VoxideClient instance (see VoxideClient.ts),
// not in this hook. That's deliberate: a session owned by a hook dies the
// moment its component unmounts, which happens for all sorts of reasons that
// have nothing to do with the user wanting to hang up (dev HMR, a re-render
// triggered by a theme change higher in the tree, switching which tab of the
// panel is showing). Owning the session on the client means it survives all
// of that — only an explicit disconnect() (the user closes the widget) ends it.
//
// useSyncExternalStore is the right primitive here: multiple mounts (or
// remounts) of this hook against the same client all read a single shared,
// external, mutable snapshot and re-render when it changes.

import { useCallback, useSyncExternalStore } from "react";
import type { VoxideClient, VoxideVoiceSnapshot } from "./VoxideClient";

export { resolveLiveUrl } from "./VoxideClient";

export interface UseVoxideVoice {
  status: VoxideVoiceSnapshot["status"];
  messages: VoxideVoiceSnapshot["messages"];
  currentAction: VoxideVoiceSnapshot["currentAction"];
  errorCode: VoxideVoiceSnapshot["errorCode"];
  connect: () => Promise<void>;
  disconnect: () => void;
  sendText: (text: string) => Promise<void>;
  interrupt: () => void;
  // ---- Wake word ----
  /** True when this project has a wake phrase AND the browser supports it.
   *  False everywhere else, so unsupported browsers render no wake-word UI. */
  wakeAvailable: boolean;
  /** True while listening locally for the phrase. */
  wakeArmed: boolean;
  /** Why arming stopped, when it did. */
  wakeFailure: VoxideVoiceSnapshot["wakeFailure"];
  /** The configured phrase, for display ("Say 'hey acme'"). */
  wakePhrase: string | null;
  /** Whether the dashboard asked for listening to start by itself. */
  wakeAutoArm: boolean;
  armWakeWord: () => void;
  disarmWakeWord: () => void;
  /** Live mic input level, 0–1 RMS. Not reactive state — poll from a rAF loop
   *  (e.g. a voice-orb visual) rather than reading it during React render. */
  getInputLevel: () => number;
  /** Live agent audio-output level, 0–1 RMS. Same polling contract as above. */
  getOutputLevel: () => number;
  // ---- End-of-conversation feedback ----
  /** Set once a conversation with a real exchange has ended and the visitor
   *  hasn't rated or dismissed it yet. Null the rest of the time. */
  endedSession: VoxideVoiceSnapshot["endedSession"];
  /** Record a 1–5 rating (+ optional comment) for that conversation. Resolves
   *  false if it couldn't be recorded; dismisses the prompt either way. */
  submitFeedback: (rating: number, comment?: string) => Promise<boolean>;
  /** Close the prompt without rating. */
  dismissFeedback: () => void;
}

const EMPTY_SNAPSHOT: VoxideVoiceSnapshot = {
  status: "idle",
  messages: [],
  currentAction: null,
  wakeArmed: false,
};

export function useVoxideVoice(client: VoxideClient | null): UseVoxideVoice {
  const subscribe = useCallback(
    (onChange: () => void) => (client ? client._subscribeVoice(onChange) : () => {}),
    [client]
  );
  const getSnapshot = useCallback(() => (client ? client._getVoiceSnapshot() : EMPTY_SNAPSHOT), [client]);
  const getServerSnapshot = useCallback(() => EMPTY_SNAPSHOT, []);

  const snapshot = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);

  const connect = useCallback(() => client?._voiceConnect() ?? Promise.resolve(), [client]);
  const disconnect = useCallback(() => client?._voiceDisconnect(), [client]);
  const sendText = useCallback((text: string) => client?._voiceSendText(text) ?? Promise.resolve(), [client]);
  const interrupt = useCallback(() => client?._voiceInterrupt(), [client]);
  const getInputLevel = useCallback(() => client?._voiceInputLevel() ?? 0, [client]);
  const getOutputLevel = useCallback(() => client?._voiceOutputLevel() ?? 0, [client]);
  const submitFeedback = useCallback(
    (rating: number, comment?: string) => client?.submitFeedback(rating, comment) ?? Promise.resolve(false),
    [client]
  );
  const dismissFeedback = useCallback(() => client?.dismissFeedback(), [client]);
  const armWakeWord = useCallback(() => client?._wakeArm(), [client]);
  // Visitor-initiated: don't re-arm after the next session, since they just
  // told us they didn't want this.
  const disarmWakeWord = useCallback(() => client?._wakeDisarm(false), [client]);

  const wakeConfig = client?._wakeConfig() ?? null;

  return {
    status: snapshot.status,
    messages: snapshot.messages,
    currentAction: snapshot.currentAction,
    errorCode: snapshot.errorCode,
    connect,
    disconnect,
    sendText,
    interrupt,
    wakeAvailable: client?._wakeAvailable() ?? false,
    wakeArmed: !!snapshot.wakeArmed,
    wakeFailure: snapshot.wakeFailure,
    wakePhrase: wakeConfig?.phrase ?? null,
    wakeAutoArm: wakeConfig?.autoArm ?? false,
    armWakeWord,
    disarmWakeWord,
    getInputLevel,
    getOutputLevel,
    endedSession: snapshot.endedSession ?? null,
    submitFeedback,
    dismissFeedback,
  };
}
